<template><div class="donut-layout"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="消息类型分布"><title>消息类型分布，共 {{ total }} 条样本</title><circle cx="60" cy="60" r="48" fill="none" stroke="var(--line)" stroke-width="13"/><circle v-for="(item,i) in segments" :key="item.type" cx="60" cy="60" r="48" fill="none" :stroke="colors[i]" stroke-width="13" :stroke-dasharray="`${item.length} ${circumference-item.length}`" :stroke-dashoffset="-item.offset"><title>{{ item.label }}：{{ item.value }} 条</title></circle></svg><div class="donut-center"><strong>{{ total.toLocaleString() }}</strong><small>样本消息</small></div></div><div class="donut-legend"><div v-for="(item,i) in items" :key="item.type"><span class="legend-dot" :style="{background:colors[i]}"/><span>{{ item.label }}</span><strong>{{ total?Math.round(item.value/total*100):0 }}%</strong></div></div></div></template>
<script>
export default {name:'TypeDonut',props:{items:{type:Array,default:()=>[]}},data(){return {colors:['var(--accent)','var(--purple)','var(--orange)','var(--blue)','var(--subtle)','var(--red)','var(--accent-strong)','var(--ink)','var(--muted)'],circumference:2*Math.PI*48}},computed:{total(){return this.items.reduce((n,i)=>n+i.value,0)},segments(){let offset=0;return this.items.map(item=>{const length=this.total?item.value/this.total*this.circumference:0;const result={...item,length,offset};offset+=length;return result})}}}
</script>
